defmodule ArchAstro.SDK.Channels.ApiActivityFeed do
  @moduledoc """
  Phoenix channel for real-time activity feed updates.

  Clients join a topic scoped to an agent or org and receive
  `new_entry` events as feed entries are created.

  ## Topics

    * `"api:activity_feed:agent:{agent_user_id}"` — entries for a specific agent
    * `"api:activity_feed:org:{org_id}"` — entries for an entire org/tenant
  """

  @spec join_agent(GenServer.server(), String.t()) ::
          {:ok, ArchAstro.SDK.Channel.t()} | {:error, ArchAstro.SDK.Error.reason()}
  def join_agent(socket, agent_id) do
    topic = "api:activity_feed:agent:#{agent_id}"

    ArchAstro.SDK.Channel.join(
      socket,
      topic,
      %{},
      ArchAstro.SDK.Channels.ApiActivityFeed,
      {:map, :unknown}
    )
  end

  @spec join_org(GenServer.server(), String.t()) ::
          {:ok, ArchAstro.SDK.Channel.t()} | {:error, ArchAstro.SDK.Error.reason()}
  def join_org(socket, org_id) do
    topic = "api:activity_feed:org:#{org_id}"

    ArchAstro.SDK.Channel.join(
      socket,
      topic,
      %{},
      ArchAstro.SDK.Channels.ApiActivityFeed,
      {:map, :unknown}
    )
  end

  @spec list_entries(
          ArchAstro.SDK.Channel.t(),
          ArchAstro.SDK.Types.ChannelPayloads.ApiActivityFeedChannel.ListEntries.Input.t(),
          timeout()
        ) ::
          {:ok, ArchAstro.SDK.Types.ChannelPayloads.ApiActivityFeedChannel.ListEntries.Response.t()}
          | {:error, ArchAstro.SDK.Error.reason()}
  def list_entries(
        channel,
        payload \\ %ArchAstro.SDK.Types.ChannelPayloads.ApiActivityFeedChannel.ListEntries.Input{},
        timeout \\ 5_000
      ) do
    ArchAstro.SDK.Channel.push(
      channel,
      "list_entries",
      payload,
      {:ref, ArchAstro.SDK.Types.ChannelPayloads.ApiActivityFeedChannel.ListEntries.Response},
      timeout
    )
  end

  @spec subscribe_new_entry(ArchAstro.SDK.Channel.t(), pid()) :: :ok
  def subscribe_new_entry(channel, subscriber \\ self()) do
    ArchAstro.SDK.Channel.subscribe(
      channel,
      "new_entry",
      subscriber,
      {:ref, ArchAstro.SDK.Types.ChannelPayloads.ApiActivityFeedChannel.NewEntry.Payload}
    )
  end

  @spec leave(ArchAstro.SDK.Channel.t()) :: :ok | {:error, ArchAstro.SDK.Error.reason()}
  def leave(channel), do: ArchAstro.SDK.Channel.leave(channel)
end
